#ifndef FECHA_H
#define FECHA_H

typedef enum {
  FALSO,
  VERDADERO
} TBool;

typedef struct {
  int dia;
  int mes;
  int anio;
} TFecha;

TFecha crear(int dia, int mes, int anio);
TBool esBisiesto(TFecha f);
int diasDelMes(TFecha f);
TFecha sumarDias(TFecha f, int n);
void mostrar(TFecha f);
int comparar(TFecha a, TFecha b);

#endif

#include <stdio.h>
#include "fecha.h"

TFecha crear(int dia, int mes, int anio) {
  TFecha f;

  f.dia = dia;
  f.mes = mes;
  f.anio = anio;
  return f;
}

TBool esBisiesto(TFecha f) {
  if ((f.anio % 4 == 0 && f.anio % 100 != 0) || f.anio % 400 == 0) {
    return VERDADERO;
  }
  return FALSO;
}

int diasDelMes(TFecha f) {
  int dias;

  if (f.mes == 2) {
    if (esBisiesto(f) == VERDADERO) {
      dias = 29;
    } else {
      dias = 28;
    }
  } else if (f.mes == 4 || f.mes == 6 || f.mes == 9 || f.mes == 11) {
    dias = 30;
  } else {
    dias = 31;
  }
  return dias;
}

TFecha sumarDias(TFecha f, int n) {
  for (int i = 0; i < n; i++) {
    f.dia = f.dia + 1;
    if (f.dia > diasDelMes(f)) {
      f.dia = 1;
      f.mes = f.mes + 1;
      if (f.mes > 12) {
        f.mes = 1;
        f.anio = f.anio + 1;
      }
    }
  }
  return f;
}

void mostrar(TFecha f) {
  printf("%d/%d/%d", f.dia, f.mes, f.anio);
}

int comparar(TFecha a, TFecha b) {
  if (a.anio != b.anio) {
    if (a.anio < b.anio) {
      return -1;
    }
    return 1;
  }
  if (a.mes != b.mes) {
    if (a.mes < b.mes) {
      return -1;
    }
    return 1;
  }
  if (a.dia != b.dia) {
    if (a.dia < b.dia) {
      return -1;
    }
    return 1;
  }
  return 0;
}

